      '切换统计周期、部门、员工或客户维度筛选时监听器立即把明细页码重置为第 1 页，统计卡、主图、辅助图和明细同步重算。',
      '统一筛选口径：部门/员工按数据负责人所属部门过滤；客户类型/来源/行业/区域按单据关联客户过滤；未建档客户（线索阶段）在启用客户维度筛选时不计入报表，避免误把线索侧数据混入客户漏斗。'
