      '回款计划状态：未回款 → 部分回款 → 已回款；已回款指财务已确认到账并按核销结果匹配到该计划期次，计划日期早于今天且未结清计为逾期（第十二章：回款录入错误走冲销，不计入已回款口径）。',
      '商机漏斗阶段顺序固定为初步接触 → 需求确认 → 方案沟通 → 报价谈判 → 商务审批 → 赢单/输单；漏斗各段宽度仅按 funnelWidth（100%/80%/60%/40%/25%/15%）绘制，规划方案 5.5 明确该比例用于展示阶段顺序、不代表实际销售转化率，也不得当作赢率展示；各阶段默认赢率为 10/25/45/65/85（赢单 100、输单 0，默认赢率为原型假设，待业务确认）；报表明细增加「加权预测金额」列 = ⌊预计金额 × 赢率 / 100⌋（按分计算），仅未结束商机（stage ≠ close）计入预测；停滞商机（flags.stalled）超过提醒阈值自动提醒并在商机分析中计数（第十二章）。',
