      '交付分析：未启动/实施中/验收中/已完成；延期 = 计划结束日期早于今天且未完成（触发预警并记录延期原因，第十二章）；验收状态由里程碑推导。',
      '服务分析：工单状态为待受理/待分派/处理中/待客户确认/已解决/已关闭/已退回，待受理+待分派+处理中+已退回视为待处理；处理时长为提交→解决的平均时长，满意度为客户评分（1–5）。'
