      '二级页签：用户管理 / 角色权限 / 组织架构 / 字典管理 / 编号规则 / 通知与提醒 / 操作日志（点击切换并同步路径）。',
      '用户管理页签：统计卡（用户总数/启用/已停用/角色数）+ 搜索筛选（关键词/部门/角色/状态）+ 表格（账号/姓名/部门/角色/电话/最近登录/状态/操作）+ 真分页。',
      '角色权限页签：左侧角色列表 + 右侧配置卡（菜单权限树勾选、数据权限单选、按钮权限多选、字段脱敏多选、角色说明）。',
      '组织架构页签：部门树（可新增子部门，每节点显示人数）+ 部门概览。',
      '字典管理页签：左侧字典分类（线索来源/客户类型/客户等级/客户行业/客户状态/客户规模/商机阶段）+ 右侧选项表（选项值/附加信息〔商机阶段显示默认赢率：初步接触 10%、需求确认 25%、方案沟通 45%、报价谈判 65%、商务审批 85%，赢单 100% / 输单 0%，默认赢率为原型假设，待业务确认〕/状态/操作）+ 新增选项输入。',
