      '数据概览统计卡 4 张（5.1 功能表第一行「客户数、商机数、预计业绩、回款额：按用户权限统计」）：我的客户（副标签本月新增 N 家）、跟进中商机（副标签待跟进 N 个 · 停滞 N 个）、本月预计成交（预计金额）、本月已回款（实际到账），全部由真实数据实算。',
      '功能区：销售漏斗（各阶段商机数量、预计金额与加权预测金额，可按本月/本季/本年切换查看；漏斗各段宽度仅为展示宽度 funnelWidth 100%/80%/60%/40%/25%，不代表转化率或赢率）与业绩进度（目标、完成额、完成率，按月/季度/年度统计）并排两卡。',
