      '按钮：同意、拒绝、退回修改、转交、加签按按钮权限启用；只有「待我审批」且当前节点轮到我时才可操作，其他角色与已处理记录只读；抄送我的视图不提供审批动作（第三章按钮权限、7.1）。',
      '数据：销售只能看到本人发起、本人待审或本人被抄送的审批；销售经理/总监按本人及下属、所属部门范围查看；管理员看全部单据（第三章数据权限）。',
      '字段：申请人、申请部门、金额、业务附件等按字段权限展示；合同成本价、报价毛利率、回款金额等敏感字段按角色脱敏或隐藏（第三章字段权限）。',
