      '统计卡：待我审批、我发起的、我已审批、平均审批用时、驳回率五张卡；待办与各视图数量取 store.approvals 实时条数，平均用时与驳回率由审批流水计算。',
      '视图页签：待我审批 / 我发起的 / 我已审批 / 抄送我的四个页签，页签标签带该视图真实数量徽标。',
      '左侧列表：每条展示标题、审批类型、申请人、提交时间、金额与状态标签，选中项高亮；无数据时显示空态。',
