      '审批类型｜类型：枚举｜必填：是｜校验：必须命中审批模板类型｜说明：覆盖规划方案 7.2 的客户转移、线索批量分配、商机特殊折扣、低价报价、合同审批、合同变更、合同终止、应收冲销，以及报价折扣、回款核销、客户合并、商机赢单等模板。',
