      '历史审批意见｜类型：对象数组（操作人/动作/意见/时间）｜必填：是｜校验：已处理动作必须留痕，时间倒序可查｜说明：7.1「历史审批意见」，提交、同意、拒绝、退回、转交、加签、抄送均写入。',
      '业务附件｜类型：文件列表｜必填：否｜校验：按字段权限查看与下载｜说明：7.1「业务附件」，如报价单、折扣申请说明；原型以标签占位展示。',
      '审批意见｜类型：长文本｜必填：拒绝/退回时必填，同意时选填｜校验：拒绝/退回为空时拦截并提示｜说明：保存到历史审批意见并通知申请人，7.2「报价审批拒绝保存拒绝原因」。',
      '转交/加签/抄送人员｜类型：人员选择｜必填：转交、加签、抄送时必填｜校验：必须为启用人员，不能为空｜说明：转交替换当前节点处理人，加签在当前节点后插入新节点，抄送仅通知不改变流程。',
      '审批状态｜类型：枚举（待审批/已同意/已拒绝/已退回修改）｜必填：是｜校验：由视图页签与处理结果推导｜说明：待我审批与我发起的未完成单据为待审批；我已审批按结果展示已同意/已拒绝/已退回修改；抄送我的为知悉状态。',
