      '审批动作全部写入历史审批意见与操作日志，记录操作人、时间、意见与动作；业务状态不能绕过审批直接修改（4.3 状态变化规则）。',
      '合同审批后修改必须按合同变更规则重新审批；已审批报价修改生成新版本，不覆盖原批准内容；回款录入错误走冲销或更正流程并保留记录（第十二章）。'
