      '流程节点状态：发起申请 done → 当前审批节点 cur → 后续节点 wait；同意后 cur→done 且下一 wait→cur；拒绝或退回后 cur→rej、流程终止；条件不满足的节点 skip；加签插入 wait 节点。',
      '审批结果：已同意（流程流转至下一节点或结束）、已拒绝（流程终止）、已退回修改（申请人可修改后重新提交）；重新提交生成新的审批实例，历史审批意见保留。',
