      '审批详情接口：返回业务单据摘要、流程节点、当前节点、历史审批意见与业务附件，并校验数据权限。',
      '审批动作接口：同意 / 拒绝 / 退回修改 / 转交 / 加签 / 抄送，服务端校验当前节点与按钮权限并写操作日志（7.1）。',
