      '按钮：所有有菜单权限的角色可使用类型筛选、时效筛选、分页和「返回审批中心」按钮（第三章按钮权限）。',
      '数据：统计范围受角色数据权限约束，部门经理仅能查看本部门及下级提交或审批的流水（第三章数据权限）。',
