      '审批类型｜类型：枚举｜必填：是｜校验：来自模板类型集合｜说明：报价折扣、合同审批、合同变更、合同终止、客户转移、商机特殊折扣、低价报价、回款核销、客户合并、线索批量分配、应收冲销等。',
