      '主线流程（规划方案 6.1）：线索来源（官网 / 市场活动 / 渠道 / 员工录入）→ 创建线索 → 系统重复检测 → 命中则提示关联已有客户或线索、人工确认合并或关联 → 分配负责人 → 销售联系并录入跟进记录 → 判断有效性 → 有效则转化客户（创建或关联客户 → 联系人 → 商机），无效则标记无效或退回公海。',
