      '线索状态｜类型：枚举（新建/跟进中/已转化/无效）｜必填：是｜校验：本页固定为已转化｜说明：状态是进入本页的必要条件。',
      '负责人｜类型：人员｜必填：否｜校验：有效销售人员｜说明：线索转化前的负责人。',
      '转化时间｜类型：日期时间｜必填：是｜校验：不早于创建时间｜说明：线索状态置为已转化时写入的时间戳。',
      '转化为客户｜类型：客户编号｜必填：是｜校验：关联客户必须存在｜说明：记录转化生成或关联的客户编号，用于跳转客户详情。'
