      '转化后线索保留原编号、公司、联系人、来源、预计金额与全部跟进历史，只追加转化时间与目标客户编号。',
      '目标客户后续可被合并或作废，合并后应通过编号映射追溯主客户，记录页不修改原转化编号。',
      '已转化线索不可再次转化，销售如需新业务应新建线索或基于客户直接新建商机。'
