      '拖拽或点击推进只能进入相邻下一阶段，跨阶段、回退和已关闭商机推进均被拦截并给出明确提示；阶段变更历史包含变更前后阶段、变更人、变更时间和备注。',
      '需求确认、方案沟通、商务审批的阶段必填项缺失时无法确认推进，补全后可成功变更并刷新卡片所在列；报价谈判无有效报价单时被拦截。',
      '赢单需合同已审批或订单已确认，禁止直接标记赢单；输单必须选择输单原因，关闭后卡片显示赢单或输单标签且赢率分别为 100% 或 0%，加权预测金额不再计入。',
      '商机超过 7 天未推进显示停滞标签并给出提醒文案，筛选、重置、看板/列表切换、卡片点击和推进按钮均可用。',
      '对应第十四章重点场景「从商机推进到报价、合同审批、签署和订单生成」：阶段推进与关联报价、合同、订单跳转链路可用，页面无控制台报错。'
