    goal: '以表格方式管理全部商机，侧重字段对比、批量选择与阶段推进操作：展示商机编号、名称、客户、联系人、来源、类型、预计金额、当前阶段、赢率、加权预测金额、预计成交日期和负责人，支持按名称/客户/编号、负责人、来源和类型筛选，并与看板共享统计口径和阶段门校验，服务销售复盘与经理管理场景。',
