      '统计卡：跟进中商机、商机预计金额、本月预计成交、加权预测金额合计（不含赢单/输单）、停滞商机、已赢单/已输单六张卡，与看板同源。',
      '筛选区：关键词输入框按商机名称、客户、编号、联系人和主要需求模糊搜索，负责人、商机来源、商机类型下拉筛选，支持查询与重置。',
      '列表区：首列为多选框，其后为商机编号、商机名称、关联客户、关联联系人、商机来源、商机类型、预计金额、当前阶段、赢率进度条、加权预测金额、预计成交日期、负责人和操作列。',
