      '关联联系人｜关联对象｜必填：是｜校验：须为该客户下的联系人｜说明：列表展示主要对接人，详情查看决策链。',
      '商机来源｜下拉框｜必填：是｜校验：线索/客户转介绍/官网/渠道/活动/广告等配置枚举｜说明：用于来源筛选和转化分析。',
