      '预计金额｜金额｜必填：是｜校验：大于 0｜说明：按元展示，已结束商机不进入跟进中金额合计。',
      '当前阶段｜下拉框｜必填：是｜校验：初步接触/需求确认/方案沟通/报价谈判/商务审批/赢单/输单｜说明：已关闭商机显示赢单或输单结果标签。',
      '赢率｜百分比｜必填：是｜校验：0 至 100，随阶段按默认赢率更新｜说明：以进度条展示，阶段推进后自动更新为该阶段默认赢率（初步接触 10%、需求确认 25%、方案沟通 45%、报价谈判 65%、商务审批 85%、赢单 100%、输单 0%，默认赢率为原型假设，待业务确认）；漏斗图的 100%/80%/60%/40%/25%/15% 仅为展示宽度（funnelWidth），不代表转化率或赢率。',
