      '竞争对手｜文本/关联｜必填：否｜校验：输单时适用则填写｜说明：记录竞争品牌与竞争态势。',
      '主要需求｜多行文本｜必填：否（进入需求确认阶段必填）｜校验：非空｜说明：客户核心需求，支持关键词搜索。',
