      '赢率｜百分比｜必填：是｜校验：0 至 100，随阶段按默认赢率更新｜说明：汇总卡与基本信息展示；各阶段默认赢率为初步接触 10%、需求确认 25%、方案沟通 45%、报价谈判 65%、商务审批 85%、赢单 100%、输单 0%（默认赢率为原型假设，待业务确认）；漏斗图的 100%/80%/60%/40%/25%/15% 仅为展示宽度（funnelWidth），不代表转化率或赢率。',
      '加权预测金额｜金额（计算）｜必填：是（汇总卡实时计算）｜校验：= ⌊预计金额 × 赢率 / 100⌋，按分计算避免浮点误差｜说明：详情汇总卡第三卡展示；仅未结束商机（stage ≠ close）计入预测，已赢单/输单商机展示「—」。',
      '预计成交日期｜日期｜必填：是｜校验：有效业务日期｜说明：预计赢单时间，用于本月预计成交和漏斗周期统计。',
      '当前阶段｜下拉框｜必填：是｜校验：初步接触/需求确认/方案沟通/报价谈判/商务审批/赢单/输单｜说明：阶段进度条高亮当前阶段；关闭后显示赢单或输单结果。',
