      '主要需求｜多行文本｜必填：否（进入需求确认阶段必填）｜校验：非空｜说明：客户核心需求，写回商机并用于方案与报价。',
      '负责人｜用户｜必填：是｜校验：在职销售人员｜说明：主销售负责人，负责推进商机。',
      '输赢单原因｜下拉框｜必填：输单时必填，赢单可选｜校验：价格偏高/功能不满足/竞品中标/客户预算取消/项目延期等配置枚举｜说明：成功或失败原因写回商机并展示在基本信息。',
      '客户需求｜多行文本｜必填：进入需求确认时必填｜校验：非空｜说明：6.3 阶段控制点，「各阶段必填信息」展示。',
      '采购时间｜日期｜必填：进入需求确认时必填｜校验：非空｜说明：评估成交周期。',
