      '方案说明｜多行文本｜必填：进入方案沟通时必填｜校验：非空｜说明：客户需求和方案记录，详情页「各阶段必填信息」展示。',
      '参与沟通的联系人｜联系人选择｜必填：进入方案沟通时必填｜校验：须为该客户下的联系人｜说明：参与联系人及决策链，「关联联系人」Tab 查看。',
      '有效报价单｜关联对象｜必填：进入报价谈判时必填｜校验：必须存在已通过审批且在有效期内的报价单｜说明：「关联报价」Tab 展示报价编号、金额、版本、有效期和审批状态。',
      '商务条件｜多行文本｜必填：进入商务审批时必填｜校验：非空｜说明：付款方式、交付周期、服务期限和折扣依据。',
      '审批材料｜附件选择｜必填：进入商务审批时必填｜校验：非空｜说明：报价单、折扣说明、客户意向函等审批材料。',
