      '进入需求确认、方案沟通、商务审批分别校验客户需求、采购时间、预算范围、方案说明、参与联系人、商务条件、审批材料等必填字段；未填项逐项标红并阻止推进。',
      '进入报价谈判前系统检查是否存在有效报价单；进入赢单前系统检查合同已审批或订单已确认；未满足时显示原因和「前往处理」链接。',
