      '每次阶段变更保留变更前后阶段、变更人、变更时间和备注；推进成功后写回阶段、赢率（取目标阶段默认赢率；赢单 100 / 输单 0）、阶段必填信息和阶段变更历史，加权预测金额同步重算。',
      '关联联系人、报价、合同、订单、附件和跟进记录均按当前商机与所属客户真实数据展示，不与其他商机混用。',
