      '按钮：财务拥有「登记收款」与收款记录页签下的「财务复核」「申请冲销」；销售只有计划详情与登记入口，财务复核按钮对非财务角色隐藏。',
      '数据：销售只能查看本人负责合同的回款计划与到账数据，财务可查看全部合同回款，销售经理可查看团队合同的逾期与回款率汇总。',
      '字段：合同金额、计划金额、已收、未收、逾期金额与核销明细对授权角色可见；审批历史与凭证附件中的敏感信息按财务字段权限控制。',
      '数据：回款记录不可物理删除，录入错误须走冲销流程并保留原记录、记录操作人（财务-王芳）与时间。'
