      '最近登录｜类型：日期时间｜必填：否｜校验：无｜说明：登录安全审计参考（第八章 登录安全：登录日志/会话管理），为空显示 —。',
      '数据权限｜类型：枚举文本｜必填：是｜校验：来自角色 dataScope 配置（本人/本部门/本部门及下级/全部，第三章）｜说明：决定该用户可访问的数据范围，在服务端校验（9.4）。',
      '菜单/按钮权限｜类型：列表｜必填：是｜校验：来自角色 menus/buttons 配置（第三章 菜单权限/按钮权限）｜说明：本页只读展示，汇总卡统计菜单数量。',
