      '移动端审批与 PC 同源：待我审批取 tab=todo，同意后进入已处理，拒绝/退回必须填写原因，处理结果即时同步 PC 审批中心计数。',
      '移动端工单按 SLA 处理：接单后进入处理中，处理完成上传现场图片并填写处理记录；超出 SLA 通知处理人及主管（7.3）。'
