      '线索流转：新建线索 → 未联系 → 跟进中 → 分配/领取 → 转化为客户/联系人/商机；原始线索与跟进历史保留（第十一章线索管理）。',
      '审批流转：待办 → 审批详情 → 同意（直接通过）/ 拒绝或退回（填原因）→ 审批中心同步可见，待办条目消失。',
